andFlagInFingerprintAndRestore|TestAccountingDetachedRestoreDiscard|TestObjectByIDFindsHandlesIncludingRestored|TestRestoredObjectInspectionKeepsDisposedState|TestListGrowthSaveRestoresRollbackCheckpoint|TestOperationDocumentationDoesNotChangeIdentity|TestGrantReleaseDoesNotChangeIdentity|TestMessagePathParentChangeRejectsDisposedChildAtDrain|TestRecoverySnapshotEveryBoundary|TestLibraryRecoverySnapshotEveryBoundary|TestPersistenceFingerprintRegistrationOrder|TestCallSettlementOwnership|TestSuspendingResultOwnership|TestOperationMalformedFailureData|TestVariablesOnlyReportsPendingScriptCalls|TestVariablesOnlyUsesRollbackBaseAndReportsScriptCall|TestAccountingVariablesOnly|TestFunctionValueMetadataSurvivesCodeChangesAndRepeatedSaves|TestPreviousLanguageSaveRejectsOrRestoresVariablesOnly|TestMalformedRecoverySnapshot|TestRecoverySaveFormatRejectsPriorTransferLayout|TestSaveFormatRejectsPriorFunctionMetadataLayout|TestRestoreRejectsMalformedFrames|TestRestoreRejectsMalformedFunctionAndQuantity)$'
# A Join member's unpaid reissue faults instead of trapping (#1068). The
# rollback base and sibling reissues in a preempted Join body remain open.
go test -tags talk_zig_experimental -run '^TestRestorePreemptedOpenJoin$/false$' -count=1 "$@" .
go test -tags talk_zig_experimental -run '^TestReissueFuelFaultSkipsSiblingHostCalls$/^0$' -count=1 "$@" .
# Cancelling a wait for removes its subscription, timer and ready event.
go test -tags talk_zig_experimental -run '^TestWaitForCancellationRemovesSubscriptionTimerAndReadyEvent$' -count=1 "$@" .
# A diamond checks each original Library site once per use (#1394).
go test -tags talk_zig_experimental -run '^TestLibraryDiamondNeedsCheckEachOriginalSiteOncePerUse$' -count=1 "$@" .
# Unknown effect state from another Script's Stop or cancel stops the Group (#1401).
go test -tags talk_zig_experimental -run '^TestFatalCrossScriptControlStopsCurrentRun$' -count=1 "$@" .
# A Limit Fault names the function it happens in (#1400).
go test -tags talk_zig_experimental -run '^TestCancellationCleanupAndNestedFaultLocation$' -count=1 "$@" .
# Load memory within the adapter's agreed limits (#1403).
go test -tags talk_zig_experimental -run '^TestLoadSourceAllocation$' -count=1 "$@" .
# Library replacement rolls back every Script before releasing any (#1402).
go test -tags talk_zig_experimental -run '^TestGrantReleaseLibraryReplacementCleanup$' -count=1 "$@" .
# Replay must offer current Library identities to Restore after replacement.
go test -tags talk_zig_experimental -run '^TestLibraryReplayAfterReplacement$' -count=1 "$@" .
# The Go Session Host, REPL and every Session Transcript (#1053).
go test -tags talk_zig_experimental -count=1 "$@" ./session
# The CLI has no tests of its own; build it so the REPL links against the adapter.
go build -tags talk_zig_experimental -o /dev/null ./cmd/northtalk
go test -tags talk_zig_experimental -run '^(TestSessionTranscriptParity|TestSessionDecomposedSourceTraceReplaysIndependently)$' -count=1 "$@" ./internal/corpus
# Large inspection Trace, reply and Save/Restore input cross chunk boundaries
# without raising the per-chunk transport limit (#1286).
go test -tags talk_zig_experimental -run '^TestLimitsStepFourAcceptance$/^limits/persistent-state-minimum$' -count=1 "$@" ./internal/corpus
# Native-Go facilities through the adapter (#1052): Pool, Store, storekit,
# the unchanged tenants example and the separate sqlite module.
go test -tags talk_zig_experimental -count=1 "$@" ./driver
go test -tags talk_zig_experimental -count=1 "$@" ./store ./internal/storekit ./examples/tenants
(cd sqlite && go test -tags talk_zig_experimental -count=1 "$@" ./...)
exec go test -tags talk_zig_experimental -run "$selection" -count=1 "$@" . ./internal/zigwasm
